//! Licence expressions such as `MIT OR Apache-2.0`.
//!
//! crates.io wants the `license` field written as an [SPDX expression]:
//! licence identifiers joined with `OR`, `AND`, `WITH` and parentheses.
//!
//! [SPDX expression]: https://spdx.github.io/spdx-spec/v2.3/SPDX-license-expressions/

// The list itself is generated by build.rs from licenses.txt. `include!`
// pastes the generated file in here, as if it had been typed.
include!(concat!(env!("OUT_DIR"), "/licenses.rs"));

/// Whether `id` is one of the [`KNOWN_LICENSES`].
///
/// # Examples
///
/// ```
/// use cargo_and_crates_io::is_known_license;
///
/// assert!(is_known_license("MIT"));
/// assert!(!is_known_license("mit")); // SPDX identifiers are case-sensitive here
/// ```
pub fn is_known_license(id: &str) -> bool {
    KNOWN_LICENSES.binary_search(&id).is_ok()
}

/// The licence identifiers in an expression that are not known.
///
/// `OR`, `AND`, parentheses, and the exception after `WITH` are skipped.
/// The old `MIT/Apache-2.0` spelling is split on `/` too.
///
/// # Examples
///
/// ```
/// use cargo_and_crates_io::licenses::unknown_licenses;
///
/// assert!(unknown_licenses("MIT OR Apache-2.0").is_empty());
/// assert!(unknown_licenses("(MIT AND Zlib) OR Apache-2.0 WITH LLVM-exception").is_empty());
/// assert_eq!(unknown_licenses("MIT OR Cheese-1.0"), ["Cheese-1.0"]);
/// ```
pub fn unknown_licenses(expression: &str) -> Vec<&str> {
    let mut unknown = Vec::new();
    let mut after_with = false;
    for word in expression
        .split(|c: char| c.is_whitespace() || c == '(' || c == ')' || c == '/')
        .filter(|w| !w.is_empty())
    {
        match word {
            "OR" | "AND" => {}
            "WITH" => after_with = true,
            _ if after_with => after_with = false, // an exception, not a licence
            id if !is_known_license(id) => unknown.push(id),
            _ => {}
        }
    }
    unknown
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_generated_list_is_sorted_and_has_the_usual_licences() {
        assert!(KNOWN_LICENSES.is_sorted());
        for id in ["MIT", "Apache-2.0", "BSD-3-Clause", "MPL-2.0"] {
            assert!(is_known_license(id), "{id}");
        }
    }

    #[test]
    fn unknown_ids_are_reported_in_order() {
        assert_eq!(unknown_licenses("Foo OR MIT AND Bar"), ["Foo", "Bar"]);
        assert_eq!(unknown_licenses("MIT/Apache-2.0"), Vec::<&str>::new());
    }
}
